import sys
from collections import deque

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None
        self.nextRight = None

def build_tree(level_order_input):
    if not level_order_input:
        return None

    nodes = [None] * len(level_order_input)
    for i, val in enumerate(level_order_input):
        if val != -1:
            nodes[i] = Node(val)

    root = nodes[0]
    queue = deque([root])
    idx = 1

    while queue and idx < len(nodes):
        current = queue.popleft()

        if idx < len(nodes) and nodes[idx] is not None:
            current.left = nodes[idx]
            queue.append(current.left)
        idx += 1

        if idx < len(nodes) and nodes[idx] is not None: 
            current.right = nodes[idx]
            queue.append(current.right)
        idx += 1

    return root

def connect(root):
    if not root:
        return

    queue = deque([root])

    while queue:
        level_size = len(queue)
        prev = None

        for _ in range(level_size):
            current = queue.popleft()

            if prev:
                prev.nextRight = current

            prev = current

            if current.left:
                queue.append(current.left)
            if current.right:
                queue.append(current.right)

        if prev:
            prev.nextRight = None

def get_level_order_with_next(root):
    result = []
    if not root:
        return result

    queue = deque([root])

    while queue:
            level_size = len(queue)
            for _ in range(level_size):
                node = queue.popleft()
                if node:
                    result.append(node.data)
                    if node.left:
                        queue.append(node.left)
                    if node.right:
                        queue.append(node.right)

    return result

def get_inorder_with_next(root):
    result = []
    stack = []
    current = root

    while stack or current:
        while current:
            stack.append(current)
            current = current.left

        current = stack.pop()
        result.append(current.data)
        current = current.right

    return result

def main():
    try:
        lines = sys.stdin.read().splitlines()
        if not lines:
            return

        level_order_data = list(map(int, lines[0].strip().split()))
        root = build_tree(level_order_data)
        connect(root)

        level_order_output = get_level_order_with_next(root)
        inorder_output = get_inorder_with_next(root)

        print(" ".join(map(str, level_order_output)))
        print(" ".join(map(str, inorder_output)))
    except Exception:
        pass

if __name__ == "__main__":
    main()
